export default {
  description: "使用 skills CLI 安裝已授權的遠端 Skill，保留附屬檔案並同步 main 與 workflow-test。",
  input: {"type":"object","properties":{"source":{"type":"string","minLength":1,"maxLength":2048}},"required":["source"],"additionalProperties":false},
  async execute(args, context) {
    const project = context.directory?.replace(/\\/g, "/").match(/\/(?:workflow\/)?projects\/([^/]+)\/?$/)?.[1];
    if (!project || !/^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/.test(project) || !context.sessionID) throw new Error("Canonical session Project context is unavailable");
    const endpoint = new URL("/bff/projects/" + encodeURIComponent(project) + "/skills/import", process.env.AGENT_SYSTEM_BFF_BASE_URL || "http://agent-system-backend:8000");
    const response = await fetch(endpoint, { method: "POST", headers: { "content-type": "application/json", "x-agent-system-workspace": project }, body: JSON.stringify({ sources: [args.source] }), signal: AbortSignal.timeout(180000) });
    const result = await response.json();
    if (!response.ok) throw new Error("Skill import failed: " + (result.error?.code || response.status));
    return { content: JSON.stringify(result), metadata: { title: "Skill CLI 安裝結果" } };
  },
};

export default {
  description: "驗證並登錄 Agent 產出的已安裝 Skill JSON Canvas reference node。",
  input: {"type":"object","properties":{"nodeJson":{"type":"string","minLength":2,"maxLength":10000}},"required":["nodeJson"],"additionalProperties":false},
  async execute(args, context) {
    const project = context.directory?.replace(/\\/g, "/").match(/\/(?:workflow\/)?projects\/([^/]+)\/?$/)?.[1];
    if (!project || !/^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/.test(project) || !context.sessionID) throw new Error("Canonical session Project context is unavailable");
    const endpoint = new URL("/bff/projects/" + encodeURIComponent(project) + "/skills/nodes", process.env.AGENT_SYSTEM_BFF_BASE_URL || "http://agent-system-backend:8000");
    const response = await fetch(endpoint, { method: "POST", headers: { "content-type": "application/json", "x-agent-system-workspace": project }, body: JSON.stringify({ node: JSON.parse(args.nodeJson) }), signal: AbortSignal.timeout(60000) });
    const result = await response.json();
    if (!response.ok) throw new Error("Skill node registration failed: " + (result.error?.code || response.status));
    return { content: JSON.stringify(result), metadata: { title: "Skill Canvas node" } };
  },
};
